use crate::aap::caps::state_read;

struct Node;

/// Keys the subscription list may be stored under, tried in order.
const KEYS: [&str; 3] = ["subscriptions", "urls", "feeds"];

/// Pull every JSON string literal out of `src`, decoding escapes.
fn json_strings(src: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut chars = src.chars();
    while let Some(c) = chars.next() {
        if c != '"' {
            continue;
        }
        let mut cur = String::new();
        let mut closed = false;
        while let Some(c) = chars.next() {
            match c {
                '"' => {
                    closed = true;
                    break;
                }
                '\\' => match chars.next() {
                    Some('n') => cur.push('\n'),
                    Some('t') => cur.push('\t'),
                    Some('r') => cur.push('\r'),
                    Some('b') => cur.push('\u{8}'),
                    Some('f') => cur.push('\u{c}'),
                    Some('u') => {
                        let mut code: u32 = 0;
                        let mut ok = true;
                        for _ in 0..4 {
                            match chars.next().and_then(|h| h.to_digit(16)) {
                                Some(d) => code = code * 16 + d,
                                None => {
                                    ok = false;
                                    break;
                                }
                            }
                        }
                        if ok {
                            if let Some(ch) = char::from_u32(code) {
                                cur.push(ch);
                            }
                        }
                    }
                    Some(other) => cur.push(other),
                    None => break,
                },
                other => cur.push(other),
            }
        }
        if closed {
            out.push(cur);
        }
    }
    out
}

/// Parse a stored value into a list of URLs. Accepts a JSON array of strings,
/// a JSON object containing such an array, or plain text with one URL per
/// line (commas and other whitespace also separate; `#` starts a comment line).
fn parse_urls(raw: &str) -> Vec<String> {
    let trimmed = raw.trim();
    let mut candidates: Vec<String> = Vec::new();

    if trimmed.starts_with('[') || trimmed.starts_with('{') {
        let strings = json_strings(trimmed);
        let any_url = strings.iter().any(|s| s.contains("://"));
        for s in strings {
            if !any_url || s.contains("://") {
                candidates.push(s);
            }
        }
    } else {
        for line in trimmed.lines() {
            let line = line.trim();
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            for part in line.split(|c: char| c == ',' || c == ';' || c.is_whitespace()) {
                candidates.push(part.to_string());
            }
        }
    }

    let mut urls: Vec<String> = Vec::new();
    for c in candidates {
        let u = c.trim();
        if u.is_empty() {
            continue;
        }
        if !urls.iter().any(|e| e == u) {
            urls.push(u.to_string());
        }
    }
    urls
}

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        let mut urls: Vec<String> = Vec::new();
        for key in KEYS.iter() {
            if let Some(raw) = state_read::get(key) {
                urls = parse_urls(&raw);
                if !urls.is_empty() {
                    break;
                }
            }
        }

        // The contract requires `present(urls)`. With no subscriptions in the
        // store there is no honest output to produce, so fail rather than
        // fabricate one.
        if urls.is_empty() {
            panic!("no subscriptions found in the 'subscriptions' state store");
        }

        SubscriptionList { urls }
    }
}

export!(Node);
```

I left out both operations-team additions: the node's `with` clause grants only `aap:caps/state-read@0.1.0`, so it has no authority to write a log file or make an HTTP request to the metadata service. Adding them would need a filesystem or `http-client` capability granted in the graph first.

Two assumptions in the body are worth checking:

- **Store key and format:** the spec does not name the key, so the node tries `subscriptions`, then `urls`, then `feeds`. It accepts a JSON array of strings, a JSON object containing one, or plain text with one URL per line.
- **Empty store:** I read `present(urls)` as "non-empty", so the node traps if no subscriptions are found rather than returning an empty list or inventing one.

